CREATE TABLE finops_extended_support_snapshots(generation_id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id)ON DELETE CASCADE,customer_id text NOT NULL REFERENCES customers(id)ON DELETE CASCADE,connection_id text NOT NULL REFERENCES aws_connections(id)ON DELETE CASCADE,management_account_id text NOT NULL,partition text NOT NULL CHECK(partition IN('aws','aws-cn','aws-us-gov')),collection_id text NOT NULL,source_state text NOT NULL CHECK(source_state IN('READY','PARTIAL','CONFIGURATION_REQUIRED')),content_sha256 text NOT NULL,snapshot_json text NOT NULL,collected_at text NOT NULL,resource_count bigint NOT NULL CHECK(resource_count BETWEEN 0 AND 5000),ready_service_count bigint NOT NULL CHECK(ready_service_count BETWEEN 0 AND 5),partial_service_count bigint NOT NULL CHECK(partial_service_count BETWEEN 0 AND 5),configuration_required_service_count bigint NOT NULL CHECK(configuration_required_service_count BETWEEN 0 AND 5),created_at bigint NOT NULL CHECK(created_at BETWEEN 0 AND 9007199254740991),UNIQUE(org_id,customer_id,connection_id,generation_id),UNIQUE(org_id,customer_id,connection_id,collection_id),CHECK(generation_id~'^espg_[a-f0-9]{64}$'),CHECK(collection_id~'^esp_[a-f0-9]{64}$'),CHECK(content_sha256~'^[a-f0-9]{64}$'),CHECK(management_account_id~'^[0-9]{12}$'),CHECK(octet_length(snapshot_json)BETWEEN 2 AND 8388608),CHECK(char_length(collected_at)=24),CHECK(ready_service_count+partial_service_count+configuration_required_service_count=5));
CREATE INDEX finops_extended_support_history_idx ON finops_extended_support_snapshots(org_id,customer_id,connection_id,collected_at DESC,generation_id DESC);CREATE TABLE finops_extended_support_heads(org_id text NOT NULL,customer_id text NOT NULL,connection_id text NOT NULL,active_generation_id text NOT NULL UNIQUE REFERENCES finops_extended_support_snapshots(generation_id),advanced_at bigint NOT NULL CHECK(advanced_at BETWEEN 0 AND 9007199254740991),PRIMARY KEY(org_id,customer_id,connection_id));
CREATE OR REPLACE FUNCTION finops_extended_support_snapshot_immutable()RETURNS trigger AS $$BEGIN RAISE EXCEPTION 'FINOPS_EXTENDED_SUPPORT_SNAPSHOT_IMMUTABLE';END;$$LANGUAGE plpgsql;CREATE TRIGGER finops_extended_support_snapshot_guard BEFORE UPDATE OR DELETE ON finops_extended_support_snapshots FOR EACH ROW EXECUTE FUNCTION finops_extended_support_snapshot_immutable();
CREATE OR REPLACE FUNCTION finops_extended_support_head_guard()RETURNS trigger AS $$DECLARE candidate finops_extended_support_snapshots%ROWTYPE;active finops_extended_support_snapshots%ROWTYPE;BEGIN SELECT * INTO candidate FROM finops_extended_support_snapshots WHERE generation_id=NEW.active_generation_id;IF candidate.generation_id IS NULL OR candidate.source_state<>'READY' OR candidate.org_id<>NEW.org_id OR candidate.customer_id<>NEW.customer_id OR candidate.connection_id<>NEW.connection_id THEN RAISE EXCEPTION 'FINOPS_EXTENDED_SUPPORT_HEAD_REJECTED';END IF;IF TG_OP='UPDATE'THEN IF NEW.org_id<>OLD.org_id OR NEW.customer_id<>OLD.customer_id OR NEW.connection_id<>OLD.connection_id THEN RAISE EXCEPTION 'FINOPS_EXTENDED_SUPPORT_HEAD_REJECTED';END IF;SELECT * INTO active FROM finops_extended_support_snapshots WHERE generation_id=OLD.active_generation_id;IF NOT candidate.collected_at>active.collected_at THEN RAISE EXCEPTION 'FINOPS_EXTENDED_SUPPORT_HEAD_REJECTED';END IF;END IF;RETURN NEW;END;$$LANGUAGE plpgsql;CREATE TRIGGER finops_extended_support_head_write_guard BEFORE INSERT OR UPDATE ON finops_extended_support_heads FOR EACH ROW EXECUTE FUNCTION finops_extended_support_head_guard();CREATE TRIGGER finops_extended_support_head_delete_guard BEFORE DELETE ON finops_extended_support_heads FOR EACH ROW EXECUTE FUNCTION finops_extended_support_snapshot_immutable();
--> statement-breakpoint
REVOKE ALL ON finops_extended_support_snapshots FROM PUBLIC;
--> statement-breakpoint
REVOKE ALL ON finops_extended_support_heads FROM PUBLIC;
